mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.APP_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.REF_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.MAP_ID,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.APP_ID = #{appId}
AND T1.MAP_TYPE_CD = #{mapTypeCd}
AND T1.REF_ID = #{refId}
AND T1.ROLE_CD = #{roleCd}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.MAP_ID AS MAP_ID, T1.APP_ID AS APP_ID, T1.MAP_TYPE_CD AS MAP_TYPE_CD,
           T1.REF_ID AS REF_ID, T1.ROLE_CD AS ROLE_CD, T1.REMARK AS REMARK,
           T1.REG_USER_ID AS REG_USER_ID, T1.REG_DTM AS REG_DTM
      FROM TB_IF_APP_MAP_PILOT T1

     ORDER BY T1.APP_ID, T1.MAP_TYPE_CD, T1.MAP_ID
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}

mapper.insert:
INSERT INTO TB_IF_APP_MAP_PILOT (
  MAP_ID, APP_ID, MAP_TYPE_CD, REF_ID, ROLE_CD, REMARK, REG_USER_ID, REG_DTM
) VALUES (
  #{mapId}, #{appId}, #{mapTypeCd}, #{refId}, #{roleCd}, #{remark}, #{regUserId}, #{regDtm}
)

mapper.delete:
DELETE FROM TB_IF_APP_MAP_PILOT
 WHERE MAP_ID IN
#{id}
